insert into public.periods (id, position, title, years, level, summary, key_points, films) values
  ('origines', 1, 'Les origines', '1895 – 1914', 1, 'Le cinéma naît à la croisée de la science, de la photographie et du spectacle forain. En quelques années, il passe de la « vue » d''une minute au récit de fiction.', array['28 décembre 1895 : première projection publique payante du Cinématographe Lumière, au Salon indien du Grand Café à Paris.', 'Les frères Lumière filment le réel (« vues ») ; Georges Méliès invente le trucage et la féerie.', 'Alice Guy réalise des fictions dès 1896 et devient la première femme cinéaste.', 'Le cinéma est d''abord une attraction de foire avant de s''installer dans des salles dédiées.'], array['La Sortie de l''usine Lumière à Lyon (1895)', 'Le Voyage dans la Lune (Méliès, 1902)', 'Le Vol du grand rapide (Porter, 1903)']),
  ('muet', 2, 'Âge d’or du muet et avant-gardes', '1915 – 1929', 1, 'Sans parole synchronisée, le cinéma invente son propre langage : le montage, le gros plan, le jeu des corps. Chaque pays développe une école.', array['Le burlesque américain : Charlie Chaplin, Buster Keaton, Harold Lloyd.', 'L''expressionnisme allemand déforme décors et lumières pour exprimer l''angoisse (Le Cabinet du docteur Caligari, 1920).', 'L''école soviétique théorise le montage : Eisenstein, Vertov, Koulechov.', 'En France, les avant-gardes (Gance, Epstein, Dulac) explorent le rythme et la subjectivité.'], array['Le Cuirassé Potemkine (Eisenstein, 1925)', 'Le Mécano de la « General » (Keaton, 1926)', 'Metropolis (Lang, 1927)']),
  ('parlant', 3, 'Le parlant et les grands studios', '1927 – 1945', 2, 'L''arrivée du son bouleverse la technique, le jeu et l''économie du cinéma. Hollywood impose le système des studios et des genres.', array['Le Chanteur de jazz (1927) popularise le film parlant.', 'Hollywood classique : studios, stars, genres codifiés (western, comédie musicale, film de gangsters).', 'En France, le réalisme poétique : Carné, Prévert, Renoir, Vigo.', 'Citizen Kane (Welles, 1941) renouvelle le récit et la profondeur de champ.'], array['M le maudit (Lang, 1931)', 'La Règle du jeu (Renoir, 1939)', 'Citizen Kane (Welles, 1941)']),
  ('apres-guerre', 4, 'Néoréalisme et après-guerre', '1945 – 1958', 2, 'Après la guerre, des cinéastes sortent des studios pour filmer la rue, les gens ordinaires et les ruines. Le cinéma devient aussi un objet de critique et de pensée.', array['Néoréalisme italien : décors réels, acteurs non professionnels, sujets sociaux (Rossellini, De Sica, Visconti).', 'Le film noir américain : ombres, fatalité, détectives et femmes fatales.', 'Le cinéma japonais est découvert en Occident avec Rashômon (Kurosawa, 1950).', 'Les Cahiers du cinéma (fondés en 1951) défendent la « politique des auteurs ».'], array['Rome, ville ouverte (Rossellini, 1945)', 'Le Voleur de bicyclette (De Sica, 1948)', 'Rashômon (Kurosawa, 1950)']),
  ('nouvelles-vagues', 5, 'Les Nouvelles Vagues', '1958 – 1968', 2, 'De jeunes cinéastes, souvent anciens critiques, tournent vite, légèrement et librement. Le mouvement part de France et essaime dans le monde entier.', array['Tournages en décors naturels, petites équipes, caméras légères, son direct.', 'Truffaut, Godard, Chabrol, Rohmer, Rivette ; et la « Rive gauche » : Varda, Resnais, Marker.', 'Ruptures de ton, regards caméra, faux raccords assumés.', 'Échos mondiaux : Free Cinema britannique, Cinema Novo brésilien, Nouvelle Vague japonaise et tchécoslovaque.'], array['Les Quatre Cents Coups (Truffaut, 1959)', 'À bout de souffle (Godard, 1960)', 'Cléo de 5 à 7 (Varda, 1962)']),
  ('nouvel-hollywood', 6, 'Le Nouvel Hollywood', '1967 – 1980', 3, 'Une génération de cinéastes formés à la cinéphilie prend le pouvoir à Hollywood, avec des films plus sombres et personnels — avant le retour du grand spectacle.', array['Influence des nouvelles vagues européennes sur le cinéma américain.', 'Anti-héros, violence, fins ouvertes, critique de la société américaine.', 'Coppola, Scorsese, Altman, De Palma, Cimino.', 'Les Dents de la mer (1975) et Star Wars (1977) inaugurent l’ère du blockbuster.'], array['Bonnie and Clyde (Penn, 1967)', 'Le Parrain (Coppola, 1972)', 'Taxi Driver (Scorsese, 1976)']),
  ('monde', 7, 'Cinémas du monde et indépendants', '1980 – 1999', 3, 'Les festivals révèlent des cinématographies de tous les continents, tandis que le cinéma indépendant et l''image de synthèse transforment les formes.', array['Reconnaissance des cinémas d''Asie et du Moyen-Orient : Wong Kar-wai, Abbas Kiarostami, Hou Hsiao-hsien.', 'Cinéma indépendant américain : Jarmusch, Spike Lee, Tarantino.', 'Dogme 95 (von Trier, Vinterberg) : un manifeste pour un cinéma dépouillé.', 'Toy Story (1995) : premier long métrage entièrement en images de synthèse.'], array['Do the Right Thing (Spike Lee, 1989)', 'La Leçon de piano (Campion, 1993)', 'Le Goût de la cerise (Kiarostami, 1997)']),
  ('numerique', 8, 'L''ère numérique', '2000 – aujourd’hui', 3, 'Le numérique change la prise de vues, le montage, la diffusion et jusqu''à la définition même du cinéma, entre salles, plateformes et écrans mobiles.', array['Les caméras numériques légères ouvrent de nouvelles écritures (Varda, Les Glaneurs et la Glaneuse, 2000).', 'La projection en salle passe de la pellicule au numérique.', 'Les plateformes de streaming deviennent productrices et diffuseuses.', 'Circulation mondiale des films : Parasite (Bong Joon-ho) remporte la Palme d’or 2019 puis l’Oscar du meilleur film.'], array['In the Mood for Love (Wong Kar-wai, 2000)', 'Les Glaneurs et la Glaneuse (Varda, 2000)', 'Parasite (Bong Joon-ho, 2019)'])
insert into public.terms (id, term, category, level, definition, example) values
  ('plan', 'Plan', 'Cadre', 1, 'Unité de base du film : suite d''images enregistrées en une seule prise, entre deux coupes.', null),
  ('cadre', 'Cadre', 'Cadre', 1, 'Limites de l''image. Cadrer, c''est choisir ce que l''on montre et ce que l''on laisse dehors.', null),
  ('champ', 'Champ / hors-champ', 'Cadre', 1, 'Le champ est la portion d''espace visible à l''image ; le hors-champ est tout ce qui existe autour sans être montré.', 'Un bruit de pas hors-champ annonce l''arrivée d''un personnage.'),
  ('echelle', 'Échelle des plans', 'Cadre', 1, 'Taille du sujet dans le cadre : plan général, plan d’ensemble, plan moyen, plan américain, plan rapproché, gros plan, très gros plan.', null),
  ('gros-plan', 'Gros plan', 'Cadre', 1, 'Cadre serré sur un visage ou un objet, qui isole un détail et intensifie l''émotion.', null),
  ('plongee', 'Plongée / contre-plongée', 'Cadre', 1, 'Angle de prise de vues : en plongée la caméra regarde vers le bas, en contre-plongée vers le haut.', null),
  ('profondeur', 'Profondeur de champ', 'Cadre', 2, 'Zone de netteté de l''image, de l''avant-plan à l''arrière-plan. Grande, elle permet de jouer sur plusieurs actions dans le même plan.', 'Citizen Kane (1941).'),
  ('panoramique', 'Panoramique', 'Mouvement', 1, 'La caméra pivote sur son axe (horizontalement ou verticalement) sans se déplacer.', null),
  ('travelling', 'Travelling', 'Mouvement', 1, 'La caméra se déplace dans l’espace : avant, arrière, latéral ou d’accompagnement.', null),
  ('plan-sequence', 'Plan-séquence', 'Mouvement', 2, 'Séquence entière filmée en un seul plan, sans coupe.', 'L''ouverture de La Soif du mal (Welles, 1958).'),
  ('camera-subjective', 'Caméra subjective', 'Mouvement', 2, 'La caméra adopte le regard d''un personnage : le spectateur voit ce qu''il voit.', null),
  ('montage', 'Montage', 'Montage', 1, 'Assemblage des plans dans un certain ordre et selon une certaine durée, qui construit le récit, le rythme et le sens.', null),
  ('raccord', 'Raccord', 'Montage', 1, 'Manière de lier deux plans pour assurer la continuité : raccord regard, raccord mouvement, raccord dans l''axe.', null),
  ('champ-contrechamp', 'Champ-contrechamp', 'Montage', 1, 'Alternance de deux plans opposés, typique des scènes de dialogue.', null),
  ('ellipse', 'Ellipse', 'Montage', 2, 'Saut dans le temps : une partie de l''histoire n''est pas montrée.', null),
  ('montage-alterne', 'Montage alterné', 'Montage', 2, 'Alternance de deux actions simultanées se déroulant dans des lieux différents.', 'Une poursuite montée avec la victime qui attend les secours.'),
  ('montage-parallele', 'Montage parallèle', 'Montage', 3, 'Alternance d''actions sans lien de simultanéité, rapprochées pour créer une comparaison ou une idée.', null),
  ('faux-raccord', 'Faux raccord / jump cut', 'Montage', 3, 'Rupture volontaire de la continuité entre deux plans, qui fait sentir la coupe.', 'À bout de souffle (Godard, 1960).'),
  ('effet-koulechov', 'Effet Koulechov', 'Montage', 3, 'Le sens d''un plan dépend des plans qui l''entourent : un même visage neutre semble exprimer des émotions différentes selon l''image qui suit.', null),
  ('son-in', 'Son in / hors-champ / off', 'Son', 2, 'Son in : sa source est visible à l''image. Hors-champ : la source appartient à la scène mais n''est pas visible. Off : il vient d''ailleurs (voix off, musique de film).', null),
  ('diegetique', 'Diégétique / extradiégétique', 'Son', 3, 'Est diégétique ce qui appartient au monde de l''histoire (une radio allumée) ; extradiégétique ce qui s''y ajoute pour le spectateur (la musique d''accompagnement).', null),
  ('clair-obscur', 'Clair-obscur', 'Lumière', 2, 'Éclairage fortement contrasté entre zones de lumière et d''ombre, emblématique de l''expressionnisme et du film noir.', null),
  ('contre-jour', 'Contre-jour', 'Lumière', 1, 'La source lumineuse est placée derrière le sujet, qui apparaît en silhouette.', null),
  ('flashback', 'Flash-back', 'Récit', 1, 'Retour en arrière dans le récit : une scène du passé vient s''insérer dans le présent de l''histoire.', null),
  ('sequence', 'Séquence', 'Récit', 1, 'Suite de plans formant une unité d''action, de lieu ou de temps — l''équivalent d''un chapitre.', null),
  ('point-de-vue', 'Point de vue', 'Récit', 2, 'Place depuis laquelle l''histoire est racontée et perçue : celle d''un personnage, de plusieurs, ou d''un narrateur extérieur.', null)
insert into public.directors (id, name, dates, country, level, bio, style, films) values
  ('guy', 'Alice Guy', '1873 – 1968', 'France / États-Unis', 1, 'Secrétaire chez Gaumont, elle tourne ses premières fictions dès 1896 puis dirige la production de la maison. Aux États-Unis, elle fonde son propre studio, la Solax. Longtemps oubliée, elle est aujourd''hui reconnue comme la première femme cinéaste.', array['Pionnière de la fiction', 'Direction d’acteurs naturelle', 'Expérimentations sonores précoces'], array['La Fée aux choux', 'La Vie du Christ (1906)', 'Falling Leaves (1912)']),
  ('melies', 'Georges Méliès', '1861 – 1938', 'France', 1, 'Illusionniste et directeur de théâtre, il découvre le Cinématographe et en fait une machine à rêves. Dans son studio de Montreuil, il invente le spectacle cinématographique et les premiers effets spéciaux.', array['Trucages (arrêt de caméra, surimpression)', 'Décors peints', 'Féerie et fantastique'], array['Le Voyage dans la Lune (1902)', 'Le Voyage à travers l’impossible (1904)']),
  ('chaplin', 'Charlie Chaplin', '1889 – 1977', 'Royaume-Uni / États-Unis', 1, 'Acteur, réalisateur, producteur et compositeur, il crée le personnage de Charlot, vagabond au grand cœur. Il mêle le rire, l''émotion et la critique sociale.', array['Burlesque et pantomime', 'Mélange de comique et de mélodrame', 'Regard sur les plus pauvres'], array['Le Kid (1921)', 'Les Temps modernes (1936)', 'Le Dictateur (1940)']),
  ('hitchcock', 'Alfred Hitchcock', '1899 – 1980', 'Royaume-Uni / États-Unis', 2, 'Surnommé le « maître du suspense », il construit ses films comme des mécaniques de précision où le spectateur en sait souvent plus que les personnages.', array['Suspense plutôt que surprise', 'Le « MacGuffin »', 'Mise en scène du regard'], array['Fenêtre sur cour (1954)', 'Sueurs froides (1958)', 'Psychose (1960)']),
  ('kurosawa', 'Akira Kurosawa', '1910 – 1998', 'Japon', 2, 'Il révèle le cinéma japonais au monde avec Rashômon. Ses films de samouraïs comme ses drames contemporains ont inspiré des cinéastes du monde entier.', array['Sens du mouvement et des éléments (pluie, vent)', 'Récits à points de vue multiples', 'Humanisme'], array['Rashômon (1950)', 'Les Sept Samouraïs (1954)', 'Ran (1985)']),
  ('varda', 'Agnès Varda', '1928 – 2019', 'France', 1, 'Photographe de formation, elle réalise La Pointe courte dès 1955, film précurseur de la Nouvelle Vague. Elle passe librement de la fiction au documentaire et à l''installation.', array['« Cinécriture »', 'Frontière poreuse entre documentaire et fiction', 'Attention aux marges et aux anonymes'], array['Cléo de 5 à 7 (1962)', 'Sans toit ni loi (1985)', 'Les Glaneurs et la Glaneuse (2000)']),
  ('truffaut', 'François Truffaut', '1932 – 1984', 'France', 1, 'Critique aux Cahiers du cinéma, il défend la « politique des auteurs » avant de passer à la réalisation. Les Quatre Cents Coups lance la Nouvelle Vague et le personnage d''Antoine Doinel.', array['Récits d’enfance et d’apprentissage', 'Amour des livres et du cinéma', 'Lyrisme discret'], array['Les Quatre Cents Coups (1959)', 'Jules et Jim (1962)', 'La Nuit américaine (1973)']),
  ('godard', 'Jean-Luc Godard', '1930 – 2022', 'France / Suisse', 2, 'Figure la plus radicale de la Nouvelle Vague, il ne cesse de remettre en question les règles du récit, du montage et du son.', array['Jump cuts et ruptures', 'Citations et collages', 'Cinéma comme essai'], array['À bout de souffle (1960)', 'Le Mépris (1963)', 'Pierrot le Fou (1965)']),
  ('kubrick', 'Stanley Kubrick', '1928 – 1999', 'États-Unis / Royaume-Uni', 3, 'Perfectionniste, il aborde un genre différent à chaque film — guerre, science-fiction, horreur, film historique — et le réinvente.', array['Symétrie et perspective centrale', 'Travellings et Steadicam', 'Usage marquant de la musique préexistante'], array['2001, l’Odyssée de l’espace (1968)', 'Barry Lyndon (1975)', 'Shining (1980)']),
  ('scorsese', 'Martin Scorsese', 'né en 1942', 'États-Unis', 3, 'Figure du Nouvel Hollywood, cinéphile passionné, il filme New York, la culpabilité et la violence. Il œuvre aussi à la restauration des films du patrimoine mondial.', array['Montage énergique', 'Voix off et musique populaire', 'Personnages tourmentés'], array['Taxi Driver (1976)', 'Raging Bull (1980)', 'Les Affranchis (1990)']),
  ('campion', 'Jane Campion', 'née en 1954', 'Nouvelle-Zélande', 3, 'Avec La Leçon de piano, elle devient en 1993 la première réalisatrice à recevoir la Palme d''or. Ses films explorent le désir et l''émancipation de personnages féminins.', array['Paysages comme états intérieurs', 'Portraits de femmes', 'Sensualité de l’image'], array['Un ange à ma table (1990)', 'La Leçon de piano (1993)', 'The Power of the Dog (2021)']),
  ('wong', 'Wong Kar-wai', 'né en 1958', 'Hong Kong', 3, 'Cinéaste de la mémoire et des amours manquées, il compose des films très stylisés où la musique, les couleurs et les ralentis disent ce que les personnages taisent.', array['Ralentis et images saccadées', 'Couleurs saturées', 'Récits fragmentés'], array['Chungking Express (1994)', 'Happy Together (1997)', 'In the Mood for Love (2000)'])
insert into public.questions (id, level, theme, question, choices, answer, explanation) values
  ('q1', 1, 'Histoire', 'Où a lieu la première projection publique payante du Cinématographe Lumière, le 28 décembre 1895 ?', array['À Lyon, dans l’usine Lumière', 'À Paris, au Grand Café', 'À Montreuil, chez Méliès', 'À New York'], 1, 'Elle se tient au Salon indien du Grand Café, boulevard des Capucines à Paris.'),
  ('q2', 1, 'Vocabulaire', 'Comment appelle-t-on un mouvement où la caméra pivote sur son axe sans se déplacer ?', array['Un travelling', 'Un zoom', 'Un panoramique', 'Un raccord'], 2, 'Dans un panoramique la caméra tourne sur elle-même ; dans un travelling elle se déplace.'),
  ('q3', 1, 'Réalisateurs', 'Qui a réalisé Le Voyage dans la Lune (1902) ?', array['Louis Lumière', 'Georges Méliès', 'Charlie Chaplin', 'Alice Guy'], 1, 'Méliès, illusionniste, est le pionnier des trucages et de la féerie au cinéma.'),
  ('q4', 1, 'Vocabulaire', 'Qu’est-ce que le hors-champ ?', array['Une scène coupée au montage', 'Ce qui existe autour du cadre sans être montré', 'Un plan filmé en extérieur', 'Le générique de fin'], 1, 'Le hors-champ est l’espace que le spectateur imagine autour de ce que le cadre montre.'),
  ('q5', 1, 'Réalisateurs', 'Quel film de François Truffaut lance la Nouvelle Vague en 1959 ?', array['À bout de souffle', 'Cléo de 5 à 7', 'Les Quatre Cents Coups', 'Jules et Jim'], 2, 'Les Quatre Cents Coups, premier long métrage de Truffaut, introduit le personnage d’Antoine Doinel.'),
  ('q6', 2, 'Histoire', 'Quelle caractéristique définit le néoréalisme italien ?', array['Des décors de studio très stylisés', 'Des tournages en décors réels avec des acteurs non professionnels', 'L’usage systématique de la couleur', 'Des récits de science-fiction'], 1, 'Rossellini ou De Sica filment dans la rue, souvent avec des non-professionnels, des sujets sociaux.'),
  ('q7', 2, 'Vocabulaire', 'Deux actions simultanées dans deux lieux différents sont montrées en alternance. C’est un montage…', array['parallèle', 'alterné', 'elliptique', 'cut'], 1, 'Le montage alterné relie des actions simultanées ; le montage parallèle rapproche des actions sans lien temporel.'),
  ('q8', 2, 'Histoire', 'Quel mouvement des années 1920 déforme décors et lumières pour exprimer l’angoisse ?', array['Le réalisme poétique', 'L’expressionnisme allemand', 'Le néoréalisme', 'Le Free Cinema'], 1, 'Le Cabinet du docteur Caligari (1920) en est le film emblématique.'),
  ('q9', 2, 'Réalisateurs', 'Quel cinéaste est surnommé le « maître du suspense » ?', array['Orson Welles', 'Akira Kurosawa', 'Alfred Hitchcock', 'Jean Renoir'], 2, 'Hitchcock distingue la surprise du suspense, où le spectateur en sait plus que le personnage.'),
  ('q10', 3, 'Vocabulaire', 'Que démontre l’effet Koulechov ?', array['Que le son modifie la perception de l’image', 'Que le sens d’un plan dépend des plans qui l’entourent', 'Que la couleur influence l’émotion', 'Qu’un plan long paraît plus réaliste'], 1, 'Un même visage neutre semble exprimer la faim, la tristesse ou le désir selon le plan qui lui est associé.'),
  ('q11', 3, 'Histoire', 'Quels films marquent, au milieu des années 1970, l’avènement du blockbuster ?', array['Easy Rider et Bonnie and Clyde', 'Les Dents de la mer et Star Wars', 'Le Parrain et Taxi Driver', 'Toy Story et Pulp Fiction'], 1, 'Les Dents de la mer (1975) puis Star Wars (1977) imposent sorties massives et grand spectacle.'),
  ('q12', 3, 'Réalisateurs', 'Qui est la première réalisatrice à avoir reçu la Palme d’or, en 1993 ?', array['Agnès Varda', 'Jane Campion', 'Chantal Akerman', 'Kathryn Bigelow'], 1, 'Jane Campion l’obtient pour La Leçon de piano.'),
  ('q13', 3, 'Vocabulaire', 'Une musique que les personnages ne peuvent pas entendre est dite…', array['diégétique', 'in', 'extradiégétique', 'synchrone'], 2, 'Elle s’ajoute au récit pour le spectateur, sans appartenir au monde de l’histoire.')
